  const splitArn = arn.split(':');
  if (splitArn.length < 6 || !splitArn[5].startsWith('task-definition/'))
    throw new Error(`Not task-definition ARN: ${arn}`);

  // Cut it down to only the fields we care about; discard the rest.
  splitArn.length = 6;
